st.markdown("<style>.stApp { background-color: #FFFFFF; color: #111111; font-family: 'Georgia', serif; } h1, h3 { text-align: center; color: #111111 !important; font-family: 'Georgia', serif; } .book-text { font-size: 1.2rem; line-height: 1.8; text-align: justify; white-space: pre-wrap; } .page-number { text-align: center; font-weight: bold; margin-top: 2rem; font-size: 1.3rem; }</style>", unsafe_allow_html=True)

